    [switch]$Apply,
    [switch]$DryRun
)

$ErrorActionPreference = 'Stop'
$ProjectRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$DocsRoot = Join-Path $ProjectRoot 'docs'
$PayloadDocs = Join-Path $ProjectRoot 'generated-docs\docs'
$NavSource = Join-Path $ProjectRoot 'mkdocs-nav.generated.yml'
$NavDestination = Join-Path $ProjectRoot 'mkdocs-nav.generated.yml'

if (-not (Test-Path $DocsRoot -PathType Container)) {
    throw "Dossier docs introuvable : $DocsRoot. Place le script à la racine du projet MkDocs."
}
if (-not $Apply -and -not $DryRun) { $DryRun = $true }

