ours/Red Team/Web/command-injection.md", "target": "01-vulnerabilites/web/server-side/command-injection/cours.md"}, {"source": "05-cours/Red Team/Web/file-inclusion-developed.md", "target": "01-vulnerabilites/web/server-side/file-inclusion/cours.md"}, {"source": "05-cours/Red Team/Web/file-upload.md", "target": "01-vulnerabilites/web/server-side/file-upload/cours.md"}, {"source": "05-cours/Red Team/Web/index.md", "target": "05-cours/red-team/web/overview-original.md"}, {"source": "05-cours/Red Team/Web/information-disclosure.md", "target": "01-vulnerabilites/web/server-side/information-disclosure/cours.md"}, {"source": "05-cours/Red Team/Web/insecure-password-reset.md", "target": "01-vulnerabilites/web/auth-controle-acces/insecure-password-reset/cours.md"}, {"source": "05-cours/Red Team/Web/path-traversal.md", "target": "01-vulnerabilites/web/server-side/path-traversal/cours.md"}, {"source": "05-cours/Red Team/Web/race-conditions.md", "target": "01-vulnerabilites/web/server-side/race-conditions/cours.md"}, {"source": "05-cours/Red Team/Web/sqli.md", "target": "01-vulnerabilites/web/server-side/sqli/cours.md"}, {"source": "05-cours/Red Team/Web/ssrf.md", "target": "01-vulnerabilites/web/server-side/ssrf/cours.md"}, {"source": "05-cours/Red Team/owasp-top10-cheatsheet.md", "target": "05-cours/red-team/owasp-top10-cheatsheet.md"}, {"source": "05-cours/Red Team/Web/api-testing.md", "target": "05-cours/red-team/web/api-testing.md"}, {"source": "06-flashcards/web/access-control.md", "target": "07-pratique/flashcards/web/access-control.md"}, {"source": "06-flashcards/web/sqli.md", "target": "07-pratique/flashcards/web/sqli.md"}]
'@
$mappings = ConvertFrom-Json -InputObject $mappingsJson

if ($DryRun -and -not $Apply) {
    Write-Host 'MODE SIMULATION : aucun fichier ne sera modifié.' -ForegroundColor Yellow
} else {
    Write-Host 'MODE APPLICATION : les fichiers vont être déplacés, sans écrasement.' -ForegroundColor Yellow
}

foreach ($item in $mappings) {
    $source = Join-Path $DocsRoot ($item.source -replace '/', '\')
    $target = Join-Path $DocsRoot ($item.target -replace '/', '\')
    if (-not (Test-Path $source -PathType Leaf)) { continue }
    if (Test-Path $target) {
        Write-Warning "Collision : la destination existe déjà. Source conservée : $($item.source) -> $($item.target)"
        continue
    }
    $targetDir = Split-Path -Parent $target
    if ($Apply) {
        New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
        Move-Item -LiteralPath $source -Destination $target
        Write-Host "Déplacé : $($item.source) -> $($item.target)"
    } else {
        Write-Host "Prévu : $($item.source) -> $($item.target)"
    }
}

if ($Apply) {
    if (Test-Path $PayloadDocs -PathType Container) {
        Get-ChildItem -LiteralPath $PayloadDocs -File -Recurse | ForEach-Object {
            $relative = $_.FullName.Substring($PayloadDocs.TrimEnd('\').Length).TrimStart('\')
            $destination = Join-Path $DocsRoot $relative
            if (-not (Test-Path $destination)) {
                $destDir = Split-Path -Parent $destination
                New-Item -ItemType Directory -Path $destDir -Force | Out-Null
                Copy-Item -LiteralPath $_.FullName -Destination $destination
                Write-Host "Créé : docs/$($relative -replace '\\','/')"
            } else {
                Write-Host "Conservé (destination existe) : docs/$($relative -replace '\\','/')" -ForegroundColor DarkGray
            }
        }
    }

    # Root home is installed from the payload only if the old page was successfully preserved/moved.
    if (Test-Path $NavSource) {
        Write-Host "Nav généré disponible : $NavSource" -ForegroundColor Green
    }
    Write-Host 'Migration appliquée. Fusionne le bloc nav dans mkdocs.yml, puis lance mkdocs build.' -ForegroundColor Green
}
